        .await
}

async fn open_runtime_db(
    &self,
    spec: RuntimeDbSpec,
    migrator: &Migrator,
    telemetry_override: Option<&dyn DbTelemetry>,
) -> anyhow::Result<SqlitePool> {
    let path = spec.path(self);
    let started = Instant::now();
    let pool_result = self
        .open_read_write_pool_with_spec(path.as_path(), Some(spec), telemetry_override)
        .await;
    telemetry::record_init_result(
        telemetry_override,
        spec.kind,
        spec.open_phase,
        started.elapsed(),
        &pool_result,
    );
    let pool = pool_result.map_err(|source| {
        RuntimeDbInitError::new(spec.label, "open", path.as_path(), source)
    })?;
    let started = Instant::now();
    let migrate_result = async {
        if matches!(spec.kind, DbKind::State) {
            repair_legacy_recency_migration_version(&pool, migrator).await?;
        }
        migrator.run(&pool).await.map_err(anyhow::Error::from)
    }
    .await;
    telemetry::record_init_result(
        telemetry_override,
        spec.kind,
        spec.migrate_phase,
        started.elapsed(),
        &migrate_result,
    );
    if let Err(source) = migrate_result {
        pool.close().await;
        return Err(
            RuntimeDbInitError::new(spec.label, "migrate", path.as_path(), source).into(),
        );
    }
    Ok(pool)

pub struct LocalThreadStore {
    pub(super) config: LocalThreadStoreConfig,
    live_recorders: Arc<Mutex<HashMap<ThreadId, LiveRecorderEntry>>>,
    pending_thread_metadata: pending_thread_metadata::PendingThreadMetadataRegistry,
    live_writer_locks: Arc<LiveWriterLocks>,
    writer_lock_coordinator: Arc<WriterLockCoordinator>,
    state_db: Option<StateDbHandle>,
    thread_history_db: Arc<OnceCell<sqlx::SqlitePool>>,
    thread_data_cleanup: Option<Arc<ThreadDataCleanup>>,
    #[cfg(test)]
    startup_migration_retry_gate: Option<Arc<StartupMigrationRetryGate>>,
}

type ThreadDataCleanup = dyn Fn(Vec<ThreadId>) -> ThreadStoreFuture<'static, ()> + Send + Sync;

type WriterLockGuard = Arc<codex_rollout::WriterLockGuard>;

struct LiveRecorderEntry {
    recorder: RolloutRecorder,
    // Rollout projection rows are keyed by immutable rollout ID, not the stable thread ID used
    // to find this live writer.
    rollout_id: ThreadId,
    // Local rollout files are materialized lazily, but metadata updates can arrive before the
    // canonical SessionMeta is durable. Retain the mode captured when live persistence was opened
    // so missing SQLite rows can still be seeded.
    history_mode: ThreadHistoryMode,
    writer_lock: WriterLockGuard,
}

pub(super) async fn shutdown_thread(
    store: &LocalThreadStore,
    thread_id: ThreadId,
) -> ThreadStoreResult<()> {
    let mut pending_metadata = store.pending_thread_metadata.lock(thread_id).await;
    let _live_writer_guard = store.live_writer_locks.lock(thread_id).await;
    let (recorder, rollout_id, history_mode) = live_writer_parts(store, thread_id).await?;
    let rollout_path = recorder.rollout_path().to_path_buf();
    if matches!(history_mode, ThreadHistoryMode::Legacy) {
        recorder.shutdown().await.map_err(thread_store_io_error)?;
    } else {
        recorder.shutdown().await.map_err(thread_store_io_error)?;
        if let Err(err) = super::thread_history_materialization::materialize_to_sqlite(
            store,
            rollout_id,
            rollout_path.as_path(),
        )
        .await
        {
            warn!("failed to project durable rollout during shutdown for {thread_id}: {err}");
        }
    }
    sync_materialized_rollout_path(store, thread_id, rollout_path.as_path()).await?;
    if let Some(metrics) = codex_otel::global()
        && let Ok(metadata) = tokio::fs::metadata(&rollout_path).await
    {
        let size_bytes = i64::try_from(metadata.len()).unwrap_or(i64::MAX);
        let _ = metrics.histogram(ROLLOUT_SIZE_BYTES_METRIC, size_bytes, &[]);
    }
    let rollout_exists = match tokio::fs::try_exists(&rollout_path).await {
        Ok(rollout_exists) => rollout_exists,
        Err(err) => {
            warn!(
                "failed to check rollout path after shutdown for {thread_id}; preserving pending metadata: {err}"
            );
            true
        }
    };
    store.live_recorders.lock().await.remove(&thread_id);
    drop(_live_writer_guard);
    if !rollout_exists && pending_metadata.take().is_some() {
        store.pending_thread_metadata.remove(thread_id).await;
    }

pub(crate) async fn add(
    &self,
    params: ThreadQueueAddParams,
) -> Result<ThreadQueueAddResponse, JSONRPCErrorError> {
    validate_user_input_image_urls(&params.input)?;
    let (thread_id, loaded_thread, source) = self.require_thread(&params.thread_id).await?;
    ensure_direct_input_allowed(loaded_thread.as_deref(), &source)?;
    let queued_item = self
        .service()?
        .enqueue(
            thread_id,
            submission_into_turn_input(params.input, Some(params.client_user_message_id)),
        )
        .await
        .map_err(queue_error)?;
    Ok(ThreadQueueAddResponse {
        queued_submission: api_queued_submission(queued_item)?,
    })

async fn require_thread(
    &self,
    raw_thread_id: &str,
) -> Result<(ThreadId, Option<Arc<CodexThread>>, SessionSource), JSONRPCErrorError> {
    let thread_id = ThreadId::from_string(raw_thread_id)
        .map_err(|error| invalid_request(format!("invalid thread id: {error}")))?;
    let (loaded_thread, source) = if let Ok(thread) =
        self.thread_manager.get_thread(thread_id).await
    {
        let snapshot = thread.config_snapshot().await;
        if snapshot.ephemeral {
            return Err(invalid_request(format!(
                "ephemeral thread does not support queued submissions: {thread_id}"
            )));
        }
        (Some(thread), snapshot.session_source)
    } else {
        let stored = self
            .thread_store
            .read_thread(ReadThreadParams {
                thread_id,
                include_archived: true,
                include_history: false,
            })
            .await
            .map_err(|error| match error {
                ThreadStoreError::ThreadNotFound { .. } => {
                    invalid_request(format!("thread not found: {thread_id}"))
                }
                error => internal_error(format!("failed to read thread: {error}")),
            })?;
        if stored.archived_at.is_some() {
            return Err(invalid_request(format!(
                "session {thread_id} is archived. Run `codex unarchive {thread_id}` to unarchive it first."
            )));
        }
        (None, stored.source)
    };

    Ok((thread_id, loaded_thread, source))

pub(super) async fn read_thread(
    store: &LocalThreadStore,
    params: ReadThreadParams,
) -> ThreadStoreResult<StoredThread> {
    let thread_id = params.thread_id;
    let sqlite_metadata = read_sqlite_metadata(store, thread_id).await;
    if !params.include_history
        && let Some((path, meta)) =
            super::live_writer::unpersisted_session_meta(store, thread_id).await
        && sqlite_metadata
            .as_ref()
            .is_none_or(|metadata| metadata.rollout_path == path && metadata.archived_at.is_none())
    {
        // A new writer already owns its metadata. Missing JSONL is intentional, so neither
        // filesystem discovery nor compression-race retries can find anything more authoritative.
        return match sqlite_metadata {
            Some(metadata) => Ok(stored_thread_from_metadata(store, metadata, Some(meta)).await),
            // Preserve the saved-thread contract used by fork/resume. A live but untouched
            // thread has no stored record yet; its absence is known without searching history.
            None => Err(ThreadStoreError::InvalidRequest {
                message: format!("no rollout found for thread id {thread_id}"),
            }),
        };
    }
    let persisted_model_settings = sqlite_metadata
        .as_ref()
        .map(|metadata| (metadata.model.clone(), metadata.reasoning_effort.clone()));
    let daybreak_enabled = sqlite_metadata
        .as_ref()
        .and_then(|metadata| metadata.daybreak_enabled);
    if let Some(metadata) = sqlite_metadata
        && (params.include_archived
            || (metadata.archived_at.is_none()
                && !rollout_path_is_archived(
                    store.config.codex_home.as_path(),
                    metadata.rollout_path.as_path(),
                )))
        && (!params.include_history
            || sqlite_rollout_path_can_load_history_for_thread(&metadata.rollout_path, thread_id)
                .await)
    {
        let metadata_sandbox_policy = metadata.sandbox_policy.clone();
        let mut thread = stored_thread_from_sqlite_metadata(store, metadata).await?;

    thread = rollout_thread;
