reject_paginated_history(&thread, params.include_history)?;
attach_history_if_requested(&mut thread, params.include_history).await?;
return Ok(thread);

pub(super) async fn unload_thread_without_subscribers(
    thread_manager: Arc<ThreadManager>,
    outgoing: Arc<OutgoingMessageSender>,
    pending_thread_unloads: PendingThreadUnloads,
    thread_state_manager: ThreadStateManager,
    thread_watch_manager: ThreadWatchManager,
    thread_id: ThreadId,
    thread: Arc<CodexThread>,
) {
    info!("thread {thread_id} has no subscribers and is idle; shutting down");

    // Any pending app-server -> client requests for this thread can no longer be
    // answered; cancel their callbacks before shutdown/unload.
    outgoing
        .cancel_requests_for_thread(thread_id, /*error*/ None)
        .await;
    thread_state_manager.remove_thread_state(thread_id).await;

    tokio::spawn(async move {
        // The deadline bounds our warning, not background cleanup. Keep polling the
        // same future so even delayed shutdown submission can eventually finish.
        let shutdown = thread.shutdown_and_wait();
        tokio::pin!(shutdown);
        let result = match tokio::time::timeout(Duration::from_secs(/*secs*/ 10), &mut shutdown)
            .await
        {
            Ok(result) => result,
            Err(_) => {
                warn!(
                    event.name = "codex.app_server.thread_shutdown_slow",
                    "thread {thread_id} shutdown is taking longer than expected; continuing to wait"
                );
                shutdown.await
            }
        };
        match result {
            Ok(()) => {
                // A delayed unload can finish after thread/revert replaces this runtime under
                // the same thread ID. Only the runtime that scheduled this unload may remove it.
                if thread_manager
                    .remove_thread_if_matches(&thread_id, &thread)
                    .await
                    .is_none()
                {
                    info!("thread {thread_id} was replaced or removed before teardown finalized");
                    pending_thread_unloads.lock().await.remove(&thread_id);

pub(super) async fn shutdown_session_runtime(sess: &Arc<Session>) {
    let startup_prewarm = {
        let mut state = sess.state.lock().await;
        // Stop admission and take the current warmup together so resume cannot replace it.
        state.shutting_down = true;
        state.take_session_startup_prewarm()
    };
    if let Some(startup_prewarm) = startup_prewarm {
        startup_prewarm.abort().await;
    }
    let _ = sess.conversation.shutdown().await;
    sess.abort_all_tasks(TurnAbortReason::Interrupted).await;
    super::async_compaction::shutdown(sess).await;
    let shell_snapshot_prewarm = sess.state.lock().await.shell_snapshot_prewarm.take();
    if let Some(shell_snapshot_prewarm) = shell_snapshot_prewarm {
        shell_snapshot_prewarm.abort();
        let _ = shell_snapshot_prewarm.await;
    }
    sess.hooks().shutdown().await;
    sess.async_hook_results.close();
    while sess.async_hook_results.try_recv().is_ok() {}
    sess.services
        .unified_exec_manager
        .terminate_all_processes()
        .await;
    if let Err(err) = sess.services.code_mode_service.shutdown().await {
        sess.services.local_agent_runtime.record_shutdown_failure(
            AgentTreeShutdownFailure::operation_failed(
                "session_shutdown",
                "code_mode",
                Some(sess.thread_id),
                "code_mode_error",
            ),
        );
        warn!("failed to shutdown code mode session: {err}");
    }
    sess.stop_mcp_prewarm_worker().await;
    {
        let _refresh = sess.mcp_refresh.acquire().await;
        sess.mcp_refresh.close();
        sess.services.mcp_runtime.shutdown().await;
    }

    sess.drain_code_mode_messages().await;

    crate::hook_runtime::run_session_end_hooks(sess).await;
    emit_thread_stop_lifecycle(sess).await;
}

async fn emit_thread_stop_lifecycle(sess: &Session) {
    for contributor in sess.services.extensions.thread_lifecycle_contributors() {
        contributor
            .on_thread_stop(codex_extension_api::ThreadStopInput {
                session_store: &sess.services.session_extension_data,
                thread_store: &sess.services.thread_extension_data,
            })
            .await;
    }
}

